import{_ as o,a8 as e,o as n,c as i,ah as l,K as a}from"./chunks/framework.CgKDWdj8.js";import"./chunks/theme.CCmhGRzB.js";const f=JSON.parse('{"title":"前端安全","description":"","frontmatter":{"title":"前端安全","abstract":"前端常见安全威胁与防御，涵盖 XSS 三种类型、CSRF 的 Token 与 SameSite 防御及点击劫持等风险应对。","created":"2026-07-10T00:00:00.000Z","tags":["Web","安全"],"type":"概念解释","category":["🛠️ 工程工具","Frontend"]},"headers":[],"relativePath":"vault/Knowledge/Engineering/前端安全.md","filePath":"vault/Knowledge/Engineering/前端安全.md","lastUpdated":1790655645000}'),s={name:"vault/Knowledge/Engineering/前端安全.md"};function h(c,t,S,b,_,p){const r=e("NolebaseGitContributors"),d=e("NolebaseGitChangelog");return n(),i("div",null,[t[0]||(t[0]=l('<h1 id="前端安全" tabindex="-1">前端安全 <a class="header-anchor" href="#前端安全" aria-label="Permalink to “前端安全”">​</a></h1><p>前端常见安全威胁及防御措施。</p><h2 id="xss-跨站脚本攻击" tabindex="-1">XSS（跨站脚本攻击） <a class="header-anchor" href="#xss-跨站脚本攻击" aria-label="Permalink to “XSS（跨站脚本攻击）”">​</a></h2><p>攻击者在网页中注入恶意脚本，在用户浏览器中执行。</p><table tabindex="0"><thead><tr><th>类型</th><th>方式</th><th>防御</th></tr></thead><tbody><tr><td>存储型 XSS</td><td>攻击代码存入服务器（如评论区）</td><td>服务端输出转义、CSP</td></tr><tr><td>反射型 XSS</td><td>恶意 URL 参数反射到页面</td><td>对用户输入做 HTML 转义</td></tr><tr><td>DOM 型 XSS</td><td>前端 JS 拼接 HTML 时注入</td><td>使用 <code>textContent</code> 而非 <code>innerHTML</code></td></tr></tbody></table><h2 id="csrf-跨站请求伪造" tabindex="-1">CSRF（跨站请求伪造） <a class="header-anchor" href="#csrf-跨站请求伪造" aria-label="Permalink to “CSRF（跨站请求伪造）”">​</a></h2><p>诱骗用户在不知情下向受信站点发送恶意请求。防御：</p><ul><li><strong>CSRF Token</strong>：服务端生成一次性 token，前端请求必须携带</li><li><strong>SameSite Cookie</strong>：<code>SameSite=Strict/Lax</code></li><li><strong>Referer/Origin 校验</strong></li></ul><h2 id="其他常见威胁" tabindex="-1">其他常见威胁 <a class="header-anchor" href="#其他常见威胁" aria-label="Permalink to “其他常见威胁”">​</a></h2><table tabindex="0"><thead><tr><th>威胁</th><th>说明</th><th>防御</th></tr></thead><tbody><tr><td>点击劫持</td><td>透明 iframe 诱骗点击</td><td><code>X-Frame-Options: DENY</code></td></tr><tr><td>HTTPS 降级</td><td>中间人攻击</td><td>HSTS 头强制 HTTPS</td></tr><tr><td>第三方脚本劫持</td><td>CDN 引入脚本被篡改</td><td>Subresource Integrity (SRI)</td></tr></tbody></table><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to “最佳实践”">​</a></h2><p>输出编码、输入校验、CSP（内容安全策略）头部、最小权限原则。</p>',12)),a(r),a(d)])}const T=o(s,[["render",h]]);export{f as __pageData,T as default};
